// issue-form.component.ts
import { Component, Inject } from '@angular/core';
import { MatDialog, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { Issue } from '../../model/issue.entity';
import { History } from '../../model/history.entity';
import { IssuesService } from '../../services/issues.service';
import { MatCardModule } from '@angular/material/card';
import { FormsModule } from "@angular/forms";
import { NgClass, NgFor } from "@angular/common";
import { MatSelectModule } from '@angular/material/select';
import { MatInputModule } from '@angular/material/input';
import { MatFormFieldModule } from '@angular/material/form-field';
import { AddHistoryEventComponent } from '../add-history-event/add-history-event.component';
import { TranslateService } from '@ngx-translate/core';
import { TranslateModule } from '@ngx-translate/core';
import {AuthenticationService} from "../../../iam/services/authentication.service";
import {SprintService} from "../../../backlog/services/sprints.service";
import {MembersService} from "../../../members/services/members.service";


@Component({
  selector: 'app-issue-form',
  standalone: true,
  imports: [MatCardModule, FormsModule, NgFor, MatFormFieldModule, MatInputModule, MatSelectModule,TranslateModule],
  templateUrl: './issue-form.component.html',
  styleUrls: ['./issue-form.component.css']
})
export class IssueFormComponent {
  newIssue: Issue;
  newHistory: History = new History();
  sprintNames: string[];
  memberNames: string[];

  constructor(
    private issuesService: IssuesService,
    private dialog: MatDialog,
    private dialogRef: MatDialogRef<IssueFormComponent>,
    @Inject(MAT_DIALOG_DATA) public data: Issue,

    private sprintsService: SprintService,
    private membersService: MembersService,

    private authService: AuthenticationService
  ) {
    this.newIssue = data ? { ...data } : new Issue();
    this.sprintNames = [];
    this.memberNames = [];
  }


  ngOnInit(): void {
    this.loadSprintsAndMembers();
  }

  private loadSprintsAndMembers(): void {
    this.authService.currentUserId.subscribe((userId: number) => {
      // Obtener nombres de sprints
      this.sprintsService.getSprintByUserId(userId).subscribe((sprints: any[]) => {
        this.sprintNames = sprints.map(sprint => sprint.title);
      });

      // Obtener nombres de miembros
      this.membersService.getMembersByUserId(userId).subscribe((members: any[]) => {
        this.memberNames = members.map(member => member.fullName);
      });
    });
  }

  onSubmit(): void {
    this.authService.currentUserId.subscribe((userId: number) => {
      function getFormattedDateTime(): string {
        return new Date().toLocaleString('es-PE', {
          year: 'numeric',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
          hour12: true
        });
      }

      const currentDateTime = getFormattedDateTime();

      if (!this.newIssue.sprintAssociate) {
        console.error('Sprint title is required');
        alert('Por favor, ingresa un título de Sprint antes de enviar el formulario.');
        return;
      }

      if (!this.newIssue.id) {
        // Crear el issue por primera vez
        this.newIssue.createdIn = currentDateTime;

        // Creación de los eventos de historial
        const creationHistory = new History();
        creationHistory.createdDate = currentDateTime;
        creationHistory.eventName = 'Creación';
        creationHistory.madeBy = this.newIssue.madeBy;
        creationHistory.description = `Issue creado por ${this.newIssue.madeBy}`;

        const assignmentHistory = new History();
        assignmentHistory.createdDate = currentDateTime;
        assignmentHistory.eventName = `Asignado a ${this.newIssue.assignedTo}`;
        assignmentHistory.madeBy = this.newIssue.madeBy;
        assignmentHistory.description = `El issue fue asignado a ${this.newIssue.assignedTo}`;

        // Crear el issue y después añadir los eventos de historial
        this.issuesService.createIssue(userId, this.newIssue).subscribe(
          (createdIssue) => {
            this.newIssue = createdIssue;

            // Añadir eventos de historial usando el issueId
            this.issuesService.addHistoryEventToIssue(this.newIssue.id, creationHistory).subscribe();
            this.issuesService.addHistoryEventToIssue(this.newIssue.id, assignmentHistory).subscribe();

            this.dialogRef.close(createdIssue);
          },
          (error) => {
            console.error('Error al crear el Issue:', error);
          }
        );
      } else {
        // Si el issue ya existe, simplemente lo actualizamos
        this.issuesService.update(this.newIssue.id, this.newIssue).subscribe(
          () => {
            this.dialogRef.close(this.newIssue);
          },
          (error) => {
            console.error('Error al actualizar el Issue:', error);
          }
        );
      }
    });
  }

    onCancel(): void {
      this.dialogRef.close(null);
    }

  addHistoryEvent(): void {
    const dialogRef = this.dialog.open(AddHistoryEventComponent, { width: '400px' });
    dialogRef.afterClosed().subscribe((result: History) => {
      if (result) {
        // Genera el próximo ID automáticamente basado en el historial actual
        const maxId = this.newIssue.history.length > 0
          ? Math.max(...this.newIssue.history.map(h => h.id))
          : 0;
        result.id = maxId + 1;

        // Agrega el nuevo evento de historial al backend si el issue ya existe
        if (this.newIssue.id) {
          this.issuesService.addHistoryEventToIssue(this.newIssue.id, result).subscribe(() => {
            console.log('Historial actualizado y guardado correctamente.');
          });
        } else {
          // Si el issue no existe, crea el issue primero
          this.authService.currentUserId.subscribe((userId: number) => {
            this.issuesService.createIssue(userId, this.newIssue).subscribe((createdIssue) => {
              this.newIssue = createdIssue;
              this.issuesService.addHistoryEventToIssue(this.newIssue.id, result).subscribe(() => {
                console.log('Nuevo issue creado y evento de historial guardado correctamente.');
              });
            });
          });
        }
      }
    });
  }
}

import { Component, OnInit } from '@angular/core'; // Importar componentes básicos de Angular
import { IssuesService } from '../../services/issues.service'; // Servicio que maneja las operaciones relacionadas con los "issues"
import { Issue } from '../../model/issue.entity'; // Modelo de datos para los "issues"
import { MatDialog } from '@angular/material/dialog'; // Servicio de Angular Material para manejar diálogos
import { IssueFormComponent } from '../../components/issue-form/issue-form.component'; // Componente para el formulario de crear/editar "issues"
import { IssueDetailsComponent } from '../../components/issue-details/issue-details.component'; // Componente para mostrar los detalles del "issue"
import { AddHistoryEventComponent } from '../../components/add-history-event/add-history-event.component'; // Componente para añadir eventos al historial
import { MatCardModule } from '@angular/material/card'; // Módulo para tarjetas de Angular Material
import { FormsModule } from '@angular/forms'; // Módulo para formularios
import { NgClass, NgFor } from '@angular/common'; // Directivas comunes de Angular
import { History } from '../../model/history.entity'; // Modelo de datos para eventos de historial
import { MatSelectModule } from '@angular/material/select'; // Módulo de selectores de Angular Material
import { MatInputModule } from '@angular/material/input'; // Módulo de inputs de Angular Material
import { MatFormFieldModule } from '@angular/material/form-field'; // Módulo para campos de formularios de Angular Material
import { TranslateService } from '@ngx-translate/core';
import { TranslateModule } from '@ngx-translate/core';
import {AuthenticationService} from "../../../iam/services/authentication.service";
import {SprintService} from "../../../backlog/services/sprints.service";

@Component({
  selector: 'app-issues-list', // Selector del componente
  standalone: true, // Indica que es un componente autónomo (standalone)
  imports: [MatCardModule, FormsModule, NgFor, MatFormFieldModule, MatInputModule, MatSelectModule,TranslateModule], // Módulos importados que el componente usará
  templateUrl: './issues-list.component.html', // Ruta de la plantilla HTML del componente
  styleUrls: ['./issues-list.component.css'] // Ruta de la hoja de estilos del componente
  })
export class IssuesListComponent implements OnInit {
  issues: Issue[] = []; // Arreglo para almacenar la lista de "issues"
  filteredIssues: Issue[] = []; // Arreglo para almacenar los "issues" filtrados

  // Listas de sprints y prioridades disponibles
  sprints: string[] = [];
  priorities: string[] = ['LOW', 'MEDIUM', 'HIGH'];

  // Variables para los filtros seleccionados
  selectedSprint: string | null = null;
  selectedPriority: string | null = null;

  // Inyección de dependencias: el servicio de "issues" y el servicio de diálogos
  constructor(private issuesService: IssuesService, private dialog: MatDialog,
              private authService: AuthenticationService,
              private sprintsService: SprintService) {}

  // Método que se ejecuta al inicializar el componente
  ngOnInit(): void {
    this.loadIssues(); // Carga los "issues" al iniciar el componente
    this.loadSprints();
  }

  private loadSprints(): void {
    this.authService.currentUserId.subscribe((userId: number) => {
      // Obtener nombres de sprints
      this.sprintsService.getSprintByUserId(userId).subscribe((sprints: any[]) => {
        this.sprints = sprints.map(sprint => sprint.title);
      });
    });
  }

  // Cargar todos los "issues" desde el servicio
  loadIssues(): void {
    this.authService.currentUserId.subscribe((userId: number) => {
      this.issuesService.getIssuesByUserId(userId).subscribe((data: Issue[]) => {
        this.issues = data; // Asigna los "issues" obtenidos
        this.filteredIssues = data; // Inicialmente, todos los "issues" están filtrados
      });
    });
  }

  // Filtrar "issues" según los criterios seleccionados (sprint y prioridad)
  filterIssues(): void {
    this.filteredIssues = this.issues.filter(issue => {
      return (!this.selectedSprint || issue.sprintAssociate === this.selectedSprint) && // Filtrar por sprint si está seleccionado
             (!this.selectedPriority || issue.priority === this.selectedPriority); // Filtrar por prioridad si está seleccionada
    });
  }

  // Abrir un diálogo para añadir un nuevo "issue"
  openAddIssueForm(): void {
    const dialogRef = this.dialog.open(IssueFormComponent, {
      width: '400px' // Tamaño del diálogo
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.issues.push(result); // Añadir el nuevo "issue" sin recargar la página
      }
    });
  }

  // Abrir un diálogo para ver más detalles de un "issue"
  openViewMore(issue: Issue): void {
    this.dialog.open(IssueDetailsComponent, {
      width: '600px', // Tamaño del diálogo
      data: issue // Pasar el "issue" como dato al componente de detalles
    });
  }

  // Abrir un diálogo para editar un "issue"
  openEditIssueForm(issue: Issue): void {
    const dialogRef = this.dialog.open(IssueFormComponent, {
      width: '400px', // Tamaño del diálogo
      data: issue // Pasar el "issue" como dato al formulario
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        const index = this.issues.findIndex(i => i.id === result.id); // Buscar el índice del "issue" editado
        if (index !== -1) {
          this.issues[index] = result; // Actualizar el "issue" en la lista
        }
      }
    });
  }

  // Eliminar un "issue"
  deleteIssue(issue: Issue): void {
    if (confirm('¿Estás seguro de que deseas eliminar este issue?')) { // Confirmar antes de eliminar
      this.issuesService.delete(issue.id).subscribe(() => {
        this.issues = this.issues.filter(i => i.id !== issue.id); // Eliminar el "issue" de la lista
        this.loadIssues();
      });
    }
  }


  // Abrir un diálogo para añadir un evento al historial de un "issue"
  addHistoryEvent(issue: Issue): void {
      const dialogRef = this.dialog.open(AddHistoryEventComponent, {
        width: '400px'
      });

      dialogRef.afterClosed().subscribe((result: History) => {
        if (result) {
          result.createdDate = new Date().toLocaleString('es-PE', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: true
          });

          // Llama al nuevo método en IssuesService para añadir el evento de historial usando el issueId
          this.issuesService.addHistoryEventToIssue(issue.id, result).subscribe(
            () => {
              console.log('Evento de historial añadido correctamente.');
              this.loadIssues(); // Opcional: actualizar la lista de issues después de añadir el evento
            },
            (error) => {
              console.error('Error al añadir el evento de historial:', error);
            }
          );
        }
      });
    }
}

import { Injectable } from '@angular/core';
import { BaseService } from "../../shared/services/base.service";
import { HttpClient } from "@angular/common/http";
import { Observable } from 'rxjs';
import { Issue } from "../model/issue.entity";
import { History } from "../model/history.entity";
@Injectable({
  providedIn: 'root'
})
export class IssuesService extends BaseService<Issue> {
  constructor(private httpClient: HttpClient) {
    super(httpClient);
    this.resourceEndpoint = '/issues';
  }

  // Nuevo método específico para IssuesService
  getAllIssues(): Observable<Issue[]> {
    return this.httpClient.get<Issue[]>(`${this.basePath}${this.resourceEndpoint}`, this.httpOptions);
  }

  getIssuesByUserId(userId: number): Observable<Issue[]> {
    return this.httpClient.get<Issue[]>(`${this.basePath}${this.resourceEndpoint}/user/${userId}`, this.httpOptions);
  }

   deleteIssue(id: number): Observable<void> {
         return this.httpClient.delete<void>(`${this.basePath}${this.resourceEndpoint}/${id}`, this.httpOptions);
       }

  // Método específico para actualizar un issue existente
    override update(id: number, issue: Issue): Observable<Issue> {
      return this.httpClient.put<Issue>(`${this.basePath}${this.resourceEndpoint}/${id}`, issue, this.httpOptions);
    }

  // Método específico para crear un nuevo issue
    createIssue(userId:number, issue: Issue): Observable<Issue> {
      const url = `${this.basePath}${this.resourceEndpoint}/${userId}`;
      return this.httpClient.post<Issue>(url, issue, this.httpOptions);
    }

   // Método específico para añadir un evento de historial a un issue dado
    addHistoryEventToIssue(issueId: number, historyEvent: History): Observable<History> {
      return this.httpClient.post<History>(
        `${this.basePath}${this.resourceEndpoint}/${issueId}/events`,
        historyEvent,
        this.httpOptions
      );
    }
}

import { v4 as uuidv4 } from 'uuid';
import { Component, EventEmitter, inject, Inject, OnInit, ViewChild } from '@angular/core';
import { FormsModule, NgForm } from "@angular/forms";
import { MatFormFieldModule } from "@angular/material/form-field";
import { MatInputModule } from "@angular/material/input";
import { MatButtonModule } from "@angular/material/button";
import { MatIconModule } from "@angular/material/icon";
import {
  MAT_DIALOG_DATA,
  MatDialogModule,
  MatDialogRef
} from "@angular/material/dialog";
import { TranslateModule } from "@ngx-translate/core";
import { MatSelectModule } from "@angular/material/select";
import { Meeting } from "../../model/meeting.entity";
import { MeetingService } from "../../services/meeting.service";
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatNativeDateModule } from '@angular/material/core';

import { NgxMaterialTimepickerModule } from 'ngx-material-timepicker';
import { MemberService } from '../../services/member.service'; // Servicio para obtener miembros

import { TranslateService } from '@ngx-translate/core';
import {AuthenticationService} from "../../../iam/services/authentication.service";

@Component({
  selector: 'app-meeting-create-and-edit',
  standalone: true,
  imports: [
    MatButtonModule,
    MatIconModule,
    MatDialogModule,
    NgxMaterialTimepickerModule,
    MatInputModule,
    MatFormFieldModule,
    FormsModule,
    TranslateModule,
    MatSelectModule,
    MatDatepickerModule,
    MatNativeDateModule,
  ],
  templateUrl: './meeting-create-and-edit.component.html',
  styleUrls: ['./meeting-create-and-edit.component.css']
})
export class MeetingCreateAndEditComponent implements OnInit {
  meeting: Meeting;
  editMode!: boolean;
  inputData: any;
  members: any[] = []; // Lista de miembros
  @ViewChild('resourceForm', { static: false }) resourceForm!: NgForm;
  //@ViewChild('pickerTime') pickerTime!: NgxMaterialTimepickerComponent;

  private meetingService: MeetingService = inject(MeetingService);
  private memberService: MemberService = inject(MemberService); // Servicio inyectado

  constructor(@Inject(MAT_DIALOG_DATA) public data: any, private dialogRef: MatDialogRef<MeetingCreateAndEditComponent>,
              private authService:AuthenticationService) {
    this.meeting = data.meeting;
    this.editMode = data.editMode;
  }

  onTimeChange(event: Event) {
    const input = event.target as HTMLInputElement;
    const timeValue = input.value; // Obtiene el valor de la hora

    // Validar el formato de la hora (ejemplo: "13:00")
    const timePattern = /^([01]\d|2[0-3]):([0-5]\d)$/;
    if (timePattern.test(timeValue)) {
      // La hora es válida, puedes procesar el valor
      console.log('Hora válida:', timeValue);
    } else {
      // La hora no es válida, puedes mostrar un mensaje de error
      console.error('Hora no válida. Usa el formato HH:mm');
    }
  }

  validateTime(event: Event) {
    const input = event.target as HTMLInputElement;
    const timeValue = input.value; // Obtiene el valor de la hora

    // Validar el formato de la hora (ejemplo: "13:00")
    const timePattern = /^([01]\d|2[0-3]):([0-5]\d)$/;

    if (!timePattern.test(timeValue) && timeValue !== '') {
      // Si la hora no es válida y el campo no está vacío, limpia el campo
      input.value = '';
      alert('Por favor, ingresa una hora válida en el formato HH:mm.');
    }
  }

  formatDate(): void {
    const dateStr = this.meeting.dateStr as any;

    if (dateStr instanceof Date && !isNaN(dateStr.getTime())) {
      this.meeting.dateStr = dateStr.toISOString().split('T')[0];
    } else if (typeof dateStr === 'string' && dateStr.trim() !== '') {
      const dateParts = dateStr.split('/');
      if (dateParts.length === 3) {
        this.meeting.dateStr = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
      }
    }
  }



  // CRUD Actions
private createResource(): void {
  const dateStr = new Date(this.meeting.dateStr);
  const formattedDate = dateStr.toISOString().split('T')[0]; // "YYYY-MM-DD"
  const formattedTime = this.meeting.timeStr; // Asumiendo que ya está en formato "HH:MM"

  this.meeting.dateStr = formattedDate;
  this.meeting.timeStr = formattedTime;

  this.meeting.members = this.members.map(m => m.id);

  this.authService.currentUserId.subscribe((userId: number) => {
    this.meetingService.create(userId, this.meeting).subscribe(response => {
      this.meeting = response;
    });
  });
}

  private updateResource(): void {
    let resourceToUpdate: Meeting = this.meeting;

    this.meetingService.update(this.meeting.id, resourceToUpdate).subscribe(response => {
      this.meeting = response;
    });
  }

  private loadMembers(): void {
    this.memberService.getAll().subscribe((members) => {
      this.members = members;
    });
  }

  // UI Event Handlers
  onSubmit(): void {
    if (this.resourceForm.form.valid) {
      if (this.editMode) {
        this.updateResource();
      } else {
        this.createResource();
      }
      this.onClose();
    } else {
      console.error('Invalid data in form');
    }
  }

  onCancel(): void {
    console.log('Submit');
  }

  onClose(): void {
    this.dialogRef.close(this.meeting); // Devuelve el objeto `meeting` creado o actualizado
  }

  ngOnInit(): void {
    this.inputData = this.data;
    this.loadMembers(); // Cargar miembros al inicializar el componente
  }
}

import { Component, Inject, Input, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { CommonModule } from '@angular/common';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { Meeting } from '../../model/meeting.entity';
import { Member } from '../../model/member.entity'; // Cambiar a Member
import { MemberService } from '../../services/member.service'; // Cambiar a MemberService
import { EditMemberDialogComponent } from '../participants/edit-participant-dialog.component';
import { TranslateService } from '@ngx-translate/core';
import { TranslateModule } from '@ngx-translate/core';
@Component({
  selector: 'app-meeting-info',
  standalone: true,
  imports: [
    CommonModule,
    MatDialogModule,TranslateModule
  ],
  templateUrl: './meeting-info.component.html',
  styleUrls: ['./meeting-info.component.css']
})
export class MeetingInfoComponent implements OnInit {
  @Input() meeting: any;
  members: Member[] = []; // Inicializa como un array vacío

  constructor(
    @Inject(MAT_DIALOG_DATA) public data: Meeting,
    private dialogRef: MatDialogRef<MeetingInfoComponent>,
    private memberService: MemberService, // Cambiar a MemberService
    private dialog: MatDialog // Inyectar MatDialog
  ) {
    this.meeting = data;
  }

  async ngOnInit() {
    this.members = await this.memberService.getAll().toPromise() || [];
  }

  getMemberNames(): string[] { // Cambiar a getMemberNames
    return this.meeting.members.map((id: number) => { // Cambiar a members
      const member = this.members.find(m => m.id === id); // Cambiar a member
      return member ? `${member.profile.fullName} ` : 'Unknown'; // Cambiar a profile
    });
  }

  getMemberName(id: number): string { // Cambiar a getMemberName
    const member = this.members.find(m => m.id === id); // Cambiar a member
    return member ? `${member.profile.fullName} ` : 'Unknown'; // Cambiar a profile
  }

  onClose(): void {
    this.dialogRef.close(this.members); // Cerrar el diálogo con la lista actualizada de miembros
  }

  copyLink(): void {
    const link = this.meeting.link;
    navigator.clipboard.writeText(link).then(() => {
      console.log('Link copied to clipboard');
    }).catch(err => {
      console.error('Could not copy link: ', err);
    });
  }

  openEditDialog(): void {
    const dialogRef = this.dialog.open(EditMemberDialogComponent, { // Cambiar a EditMemberDialogComponent
      data: {
        members: this.members, // Cambiar a members
        meetingMembers: this.meeting.members, // Cambiar a members
        meeting: this.meeting // Pasa la reunión completa
      }
    });

