      width: '400px',
      height: '600px',
      data: member // Pasamos el miembro actual para editar
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        // Actualizar el miembro editado en la lista local
        const index = this.members.findIndex(m => m.id === result.id);
        if (index !== -1) {
          this.members[index] = result; // Reemplazamos el miembro editado en la lista local
        }
      }
    });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse, HttpHeaders } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, retry } from 'rxjs/operators';
import { environment } from '../../../environments/environment';  // Importa la configuración de environment

@Injectable({
  providedIn: 'root',
})
export class BaseService<T> {
  protected basePath: string = `${environment.serverBasePath}/members`;  // URL base desde environment.ts

  protected httpOptions = {
    headers: new HttpHeaders({
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${localStorage.getItem('token') || ''}`, // Incluye el token si existe
    }),
  };

  constructor(protected http: HttpClient) {}

  // Manejo de errores
  protected handleError(error: HttpErrorResponse): Observable<never> {
    const errorMessage =
      error.error instanceof ErrorEvent
        ? `Error en la solicitud: ${error.error.message}`
        : `Código de error: ${error.status}, Mensaje: ${error.message}`;
    console.error('Error:', errorMessage);
    return throwError(() => new Error(errorMessage));
  }

  // Crear un nuevo elemento
  create(item: T): Observable<T> {
    return this.http
      .post<T>(this.basePath, item, this.httpOptions)
      .pipe(retry(2), catchError(this.handleError));
  }

  // Eliminar un elemento por ID
  delete(id: number | string): Observable<void> {
    return this.http
      .delete<void>(`${this.basePath}/${id}`, this.httpOptions)
      .pipe(retry(2), catchError(this.handleError));
  }

  // Actualizar un elemento por ID
  update(id: number | string, item: T): Observable<T> {
    return this.http
      .put<T>(`${this.basePath}/${id}`, item, this.httpOptions)
      .pipe(retry(2), catchError(this.handleError));
  }

  // Obtener todos los elementos
  getAll(): Observable<T[]> {
    return this.http
      .get<T[]>(this.basePath, this.httpOptions)
      .pipe(retry(2), catchError(this.handleError));
  }

  // Obtener un elemento por ID
  getById(id: number | string): Observable<T> {
    return this.http
      .get<T>(`${this.basePath}/${id}`, this.httpOptions)
      .pipe(retry(2), catchError(this.handleError));
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Member } from '../model/member.entity';
import { environment } from '../../../environments/environment';  // Asegúrate de usar la ruta correcta

@Injectable({
  providedIn: 'root',
})
export class MembersService {
  private apiUrl = `${environment.serverBasePath}/members`;  // Usa la URL base desde environment.ts

  constructor(private http: HttpClient) {}

  private getAuthHeaders(): HttpHeaders {
    const token = localStorage.getItem('token') || '';
    return new HttpHeaders({
      'Content-Type': 'application/json',
      'Authorization': token ? `Bearer ${token}` : '',  // Si no hay token, no se incluye
    });
  }

  // Obtener todos los miembros
  getAllMembers(): Observable<Member[]> {
    return this.http.get<Member[]>(this.apiUrl, { headers: this.getAuthHeaders() });
  }

  //obetener miembros por id de usuario
  getMembersByUserId(userId: number): Observable<Member[]> {
    return this.http.get<Member[]>(`${this.apiUrl}/user/${userId}`, { headers: this.getAuthHeaders() });
  }

  // Crear un miembro
  create(userId: number, member: Member): Observable<Member> {
    const url = `${this.apiUrl}/${userId}`;
    return this.http.post<Member>(url, member, { headers: this.getAuthHeaders() });
  }

  // Actualizar un miembro
  update(id: number, member: Member): Observable<Member> {
    return this.http.put<Member>(`${this.apiUrl}/${id}`, member, { headers: this.getAuthHeaders() });
  }

  // Eliminar un miembro
  delete(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`, { headers: this.getAuthHeaders() });
  }
}

