import { Component, OnInit } from '@angular/core';
import { StatisticsService } from '../../services/statistics.service';
import { ApexAxisChartSeries, ApexChart, ApexDataLabels, ApexPlotOptions, ApexYAxis } from 'ng-apexcharts';
import { RouterModule } from '@angular/router';
import { NgApexchartsModule } from 'ng-apexcharts';
import { CommonModule } from '@angular/common';
import { StatisticsChartComponent } from '../../components/statistics-chart/statistics-chart.component';
import { TranslateModule } from '@ngx-translate/core';
import {AuthenticationService} from "../../../iam/services/authentication.service";

export type ChartOptions = {
  series: ApexAxisChartSeries;
  chart: ApexChart;
  dataLabels: ApexDataLabels;
  plotOptions: ApexPlotOptions;
  yaxis: ApexYAxis;
};

@Component({
  standalone: true,
  selector: 'app-statistics-page',
  templateUrl: './statistics-page.component.html',
  styleUrls: ['./statistics-page.component.css'],
  imports: [CommonModule, RouterModule, NgApexchartsModule, StatisticsChartComponent, TranslateModule],
})
export class StatisticsPageComponent implements OnInit {
  public chartOptions: Partial<ChartOptions>;
  public members: any[] = [];
  public userStories: any[] = [];
  public sprints: any[] = [];
  public isLoadingStories: boolean = true;
  public isLoadingMembers: boolean = true;
  public errorMessage: string | null = null;

  constructor(private statisticsService: StatisticsService, private authService: AuthenticationService) {
    this.chartOptions = {
      series: [],
      chart: {
        type: 'bar',
        height: 350,
      },
      plotOptions: {
        bar: {
          horizontal: true,
        },
      },
      dataLabels: {
        enabled: true,
      },
      yaxis: {
        min: 0,
        max: 10,
        tickAmount: 10,
        labels: {
          formatter: (val) => `${val}`,
        },
      },
    };
  }

  ngOnInit(): void {
    this.loadUserStories();
    this.loadMembers();
    this.loadSprints();
  }

  private loadUserStories(): void {
    this.authService.currentUserId.subscribe({
      next: (userId) => {
        this.statisticsService.loadUserStories(userId).subscribe({
          next: (userStories) => {
            console.log('User Stories cargadas:', userStories);

            // Asegúrate de que los Sprints están cargados correctamente
            this.statisticsService.getSprintsByUserId(userId).subscribe({
              next: (sprints) => {
                console.log('Sprints cargados:', sprints);

                // Asocia los sprints completos a las historias de usuario
                userStories = userStories.map((story) => {
                  const sprint = sprints.find((sprint) => sprint.id === story.sprintId); // Busca el Sprint correcto
                  return {
                    ...story,
                    sprint: sprint || null, // Asocia el objeto Sprint completo
                  };
                });

                console.log('User Stories con Sprints:', userStories);

                // Filtrar los sprints únicos desde las user stories
                const sprintsIds = Array.from(new Set(userStories.map((story) => story.sprint?.id)));
                console.log('Sprints encontrados:', sprintsIds);

                // Crear la serie de datos para el gráfico
                const seriesData = sprintsIds.map((sprintId) => {
                  const sprintData = userStories.filter((story) => story.sprint?.id === sprintId);

                  console.log(`Historias de usuario para Sprint ${sprintId}:`, sprintData);

                  // Resumir los datos por estado
                  const inProgress = sprintData.filter((story) => story.status === 'TO_DO').length;
                  const complete = sprintData.filter((story) => story.status === 'DONE').length;

                  return {
                    sprint: sprintId ? `Sprint ${sprintId}` : 'Desconocido', // Asegurándote de que 'sprint' no sea undefined
                    inProgress,
                    complete,
                  };
                });

                console.log('Datos para el gráfico:', seriesData);

                // Configurar las opciones del gráfico
                this.chartOptions = {
                  series: [
                    {
                      name: 'TO_DO',
                      data: seriesData.map((data) => ({
                        x: data.sprint,
                        y: data.inProgress,
                      })),
                    },
                    {
                      name: 'DONE',
                      data: seriesData.map((data) => ({
                        x: data.sprint,
                        y: data.complete,
                      })),
                    },
                  ],
                };
              },
              error: (err) => {
                console.error('Error al cargar los Sprints:', err);
              },
            });
          },
          error: (err) => {
            console.error('Error al cargar las historias de usuario:', err);
          },
        });
      },
      error: (err) => {
        console.error('Error al obtener el ID del usuario:', err);
      },
    });
  }

  private loadMembers(): void {
    this.authService.currentUserId.subscribe({
      next: (userId) => {
        this.statisticsService.getMembers(userId).subscribe({
          next: (members) => {
            console.log('Members cargados:', members);
            this.members = members;
            this.isLoadingMembers = false;
          },
          error: (error) => {
            this.isLoadingMembers = false;
            this.errorMessage = 'Error al cargar miembros';
            console.error('Error al cargar miembros:', error);
          },
        });
      },
      error: (error) => {
        this.isLoadingMembers = false;
        this.errorMessage = 'Error al obtener el ID del usuario';
        console.error('Error al obtener el ID del usuario:', error);
      },
    });
  }

  private loadSprints(): void {
    this.authService.currentUserId.subscribe({
      next: (userId) => {
        this.statisticsService.getSprintsByUserId(userId).subscribe({
          next: (sprints) => {
            console.log('Sprints cargados:', sprints);
            this.sprints = sprints;
          },
          error: (error) => {
            console.error('Error al cargar sprints:', error);
          },
        });
      },
      error: (error) => {
        console.error('Error al obtener el ID del usuario:', error);
      },
    });
  }
}

import { Component, OnInit, AfterViewInit, ViewChild } from '@angular/core';
import { StatisticsService } from '../../services/statistics.service';
import { Sprint } from '../../model/statistic-entity/sprint.entity';
import { CommonModule } from '@angular/common';
import { NgApexchartsModule } from 'ng-apexcharts';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { TranslateModule } from '@ngx-translate/core';
import { ChartComponent } from 'ng-apexcharts';
import {AuthenticationService} from "../../../iam/services/authentication.service";

@Component({
  selector: 'app-timeline-page',
  templateUrl: './timeline-page.component.html',
  styleUrls: ['./timeline-page.component.css'],
  standalone: true,
  imports: [CommonModule, NgApexchartsModule, TranslateModule]
})
export class TimelinePageComponent implements OnInit, AfterViewInit {
  @ViewChild("chart") chart!: ChartComponent;
  sprints: Sprint[] = [];
  userStories: any[] = [];
  chartOptions: any = {};
    public isLoadingMembers: boolean = true;

    public members: any[] = [];


  private sprintColors: { [key: number]: string } = {
    1: '#FF5733',
    2: '#33FF57',
    3: '#3357FF',
    4: '#F33FFF',
  };

  constructor(
    private statisticsService: StatisticsService,
    private router: Router,
    private translate: TranslateService,
    private authService: AuthenticationService
  ) {
    this.translate.setDefaultLang('en');
  }

  ngOnInit() {
    this.initializeChartOptions();
    this.loadSprints();
    this.loadUserStories();
        this.loadMembers();

  }

  ngAfterViewInit() {
    // Verifica si el gráfico ya está cargado y si la serie ya está disponible
    if (this.chartOptions.series.length > 0) {
      this.initializeChart();
    }
  }

  initializeChartOptions() {
    this.chartOptions = {
      series: [],
      chart: {
        height: 350,
        type: "rangeBar",
        toolbar: { show: true }
      },
      plotOptions: {
        bar: {
          horizontal: true,
          barHeight: '100%',
        }
      },
      xaxis: {
        type: 'datetime',
        labels: { format: 'dd MMM' },
      },
      yaxis: {
        labels: { style: { fontSize: '12px' } }
      },
      legend: { show: false },
    };
  }

  loadSprints() {
    this.authService.currentUserId.subscribe((userId) => {
      this.statisticsService.getSprintsByUserId(userId).subscribe({
        next: (sprints) => {
          console.log('Sprints cargados:', sprints);
          this.sprints = sprints;
          if (this.sprints.length > 0) {
            this.updateChartSeries();
          } else {
            console.error('No se encontraron sprints.');
          }
        },
        error: (error) => console.error('Error al cargar sprints:', error)
      });
    });
  }

  loadUserStories() {
    this.authService.currentUserId.subscribe((userId) => {
      this.statisticsService.getUserStories(userId).subscribe({
        next: (stories) => {
          console.log('User Stories cargadas:', stories);
          this.userStories = stories;
        },
        error: (error) => console.error('Error al cargar user stories:', error)
      });
    });
  }

  initializeChart() {
    if (this.chart) {
      this.chart.updateOptions(this.chartOptions);
    } else {
      console.error('El elemento del gráfico no está inicializado.');
    }
  }

  updateChartSeries() {
    const seriesData = this.sprints.map(sprint => {
      return {
        name: `Sprint ${sprint.id}`,
        data: [
          {
            x: `Sprint ${sprint.id}`,
            y: [
              new Date(sprint.startDate).getTime(),
              new Date(sprint.endDate).getTime()
            ],
            fillColor: this.getColorBySprint(sprint.id)
          }
        ]
      };
    });

    this.chartOptions.series = seriesData;

    if (this.chart) {
      this.chart.updateOptions(this.chartOptions);
    } else {
      console.warn("Gráfico no disponible en el momento de la actualización, esperando ngAfterViewInit.");
    }
  }

  getColorBySprint(sprintId: number): string {
    return this.sprintColors[sprintId] || 'white';
  }

  navigateToStatistics() {
    this.router.navigate(['/statistics']);
  }
  private loadMembers(): void {
    this.authService.currentUserId.subscribe((userId) => {
      this.statisticsService.getMembers(userId).subscribe({
        next: (members) => {
          console.log('Members cargados:', members);
          this.members = members;
          this.isLoadingMembers = false;
        },
        error: (error) => {
          this.isLoadingMembers = false;
          console.error('Error al cargar miembros:', error);
        },
      });
    });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

import { Statistics } from '../model/statistic-entity/statistic.entity';
import { Member } from '../model/member-entity/member.entity';
import { Sprint } from '../model/statistic-entity/sprint.entity';
import { environment } from '../../../environments/environment';  // Importa el entorno

@Injectable({
  providedIn: 'root',
})
export class StatisticsService {
  private apiUrl = `${environment.serverBasePath}`;  // Corregido para usar template literal

  constructor(private http: HttpClient) {}

  getUserStories(userId: number): Observable<Statistics[]> {
    return this.http.get<Statistics[]>(`${this.apiUrl}/user-stories/user/${userId}`).pipe(
      map((stories) => {
        // Si las historias pueden tener status null, quita el filtro
        return stories;  // Eliminamos el filtro
      })
    );
  }

  loadUserStories(userId: number): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/user-stories/user/${userId}`).pipe(
      map((stories) =>
        stories.map((story) => ({
          id: story.id,
          status: story.status,
          title: story.title,
          sprintId: story.sprintId,
        }))
      )
    );
  }


  // Método para obtener los Sprints desde la API
  getSprints(): Observable<Sprint[]> {
    return this.http.get<Sprint[]>(`${this.apiUrl}/sprints`);
  }

  //Metodo para obtener sprints por id de usuario
  getSprintsByUserId(userId: number): Observable<Sprint[]> {
    return this.http.get<Sprint[]>(`${this.apiUrl}/sprints/user/${userId}`);
  }

  // Método para obtener los miembros por userId con token
  getMembers(userId: number): Observable<Member[]> {
    const token = localStorage.getItem('token');  // Obtén el token de localStorage

    // Asegúrate de que el token existe antes de agregarlo a las cabeceras
    const headers = new HttpHeaders({
      'Content-Type': 'application/json',
      'Authorization': token ? `Bearer ${token}` : ''
    });

    return this.http.get<Member[]>(`${this.apiUrl}/members/user/${userId}`, { headers });
  }

  // Método para obtener los roles de los miembros por userId con token
  getMemberRoles(userId: number): Observable<string[]> {
    const token = localStorage.getItem('token');

    const headers = new HttpHeaders({
      'Content-Type': 'application/json',
      'Authorization': token ? `Bearer ${token}` : ''
    });

    return this.http.get<Member[]>(`${this.apiUrl}/members/user/${userId}`, { headers }).pipe(
      map(members => members.map(member => member.role))
    );
  }
}

